mapper.select:
SELECT
    ,
    distance
FROM (
    SELECT
        ,
        6371 * ACOS(
            COS(RADIANS(#{request.userLat})) * COS(RADIANS(latitude))
            * COS(RADIANS(longitude) - RADIANS(#{request.userLon}))
            + SIN(RADIANS(#{request.userLat})) * SIN(RADIANS(latitude))
        ) AS distance
    FROM facility
    WHERE latitude IS NOT NULL
      AND longitude IS NOT NULL
) searched_facility


        AND (
            old_address LIKE CONCAT('%', #{request.keyword}, '%')
            OR new_address LIKE CONCAT('%', #{request.keyword}, '%')
        )




                AND (
                    facility_score < #{request.lastValue}
                    OR (
                        facility_score = #{request.lastValue}
                        AND id < #{request.lastId}
                    )
                )


                AND (
                    distance > #{request.lastValue}
                    OR (
                        distance = #{request.lastValue}
                        AND id > #{request.lastId}
                    )
                )






        ORDER BY facility_score DESC, id DESC


        ORDER BY distance ASC, id ASC


LIMIT #{request.size}
